package com.jiugeng.erp.supplier;
import static com.jiugeng.erp.supplier.SupplierTypes.*;import com.jiugeng.erp.catalogmedia.CatalogImageGateway;import com.jiugeng.erp.iam.*;import java.net.URI;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class SupplierService implements SupplierAssignmentGateway{private final SupplierRepository repo;private final CatalogImageGateway images;private final AuditTrail audit;
SupplierService(SupplierRepository repo,CatalogImageGateway images,AuditTrail audit){this.repo=repo;this.images=images;this.audit=audit;}
@Transactional(readOnly=true)Page<View> list(String q,Status status,int page,int size){return new Page<>(repo.list(q,status,page,size),repo.count(q,status),page,size);}
@Transactional(readOnly=true)View get(String id){return repo.find(id).orElseThrow(()->missing(id));}
@Transactional View create(Input raw,AuthenticatedActor actor){Input i=valid(raw,false);String id=UUID.randomUUID().toString();repo.insert(id,i,actor.userId());images.attach(i.qrImageId(),CatalogImageGateway.Purpose.SUPPLIER_QR,"SUPPLIER",id,actor);View value=get(id);audit(actor,"SUPPLIER_CREATE",id,null,snapshot(value));return value;}
@Transactional View update(String id,Input raw,AuthenticatedActor actor){View before=get(id);Input i=valid(raw,true);long version=raw.version()==null?-1:raw.version();if(repo.update(id,i,actor.userId(),version)!=1)throw conflict();images.attach(i.qrImageId(),CatalogImageGateway.Purpose.SUPPLIER_QR,"SUPPLIER",id,actor);images.releaseReplaced(before.qrImageId(),i.qrImageId(),"SUPPLIER",id);View after=get(id);audit(actor,"SUPPLIER_UPDATE",id,snapshot(before),snapshot(after));return after;}
@Transactional View disable(String id,long version,AuthenticatedActor actor){View before=get(id);Input i=new Input(before.name(),before.contactPerson(),before.phone(),before.sourceUrl(),before.qrImageId(),before.remark(),Status.DISABLED,version);return update(id,i,actor);}
@Transactional(readOnly=true)List<LinkView> variantLinks(String id){return repo.links("product_variant_supplier","variant_id",id);}
@Transactional(readOnly=true)List<LinkView> materialLinks(String id){return repo.links("auxiliary_material_supplier","auxiliary_material_id",id);}
@Transactional void replaceMaterialLinks(String id,List<LinkInput> values,AuthenticatedActor actor){replace("auxiliary_material_supplier","auxiliary_material_id",id,values,actor);audit(actor,"MATERIAL_SUPPLIERS_REPLACE",id,null,Map.of("supplierIds",values.stream().map(LinkInput::supplierId).toList()));}
@Override @Transactional public void replaceVariantAssignments(String id,List<Assignment> values,AuthenticatedActor actor){try{List<LinkInput> links=(values==null?List.<Assignment>of():values).stream().map(v->new LinkInput(v.supplierId(),v.purchaseUrl(),v.remark(),v.primary())).toList();replace("product_variant_supplier","variant_id",id,links,actor);}catch(SupplierException e){throw new SupplierAssignmentGateway.AssignmentException(e.status(),e.code(),e.getMessage());}}
private void replace(String table,String ownerColumn,String owner,List<LinkInput> raw,AuthenticatedActor actor){List<LinkInput> values=raw==null?List.of():raw;if(values.size()>50)throw invalid("关联供应商不得超过 50 个");Set<String> ids=new HashSet<>();long primary=0;List<LinkInput> valid=new ArrayList<>();for(LinkInput i:values){String id=required(i.supplierId(),"供应商",36);if(!ids.add(id))throw invalid("供应商不可重复关联");if(!repo.active(id))throw new SupplierException(409,"ACTIVE_SUPPLIER_REQUIRED","只能关联启用供应商");if(i.primary())primary++;valid.add(new LinkInput(id,url(i.purchaseUrl()),optional(i.remark(),500),i.primary()));}if(primary>1)throw invalid("最多设置一个主供应商");repo.deleteLinks(table,ownerColumn,owner);valid.forEach(i->repo.insertLink(table,ownerColumn,owner,i,actor.userId()));}
private Input valid(Input raw,boolean existing){if(raw==null)throw invalid("供应商请求不能为空");String name=required(raw.name(),"供应商名称",128),contact=optional(raw.contactPerson(),64),phone=optional(raw.phone(),32),source=url(raw.sourceUrl()),qr=optional(raw.qrImageId(),36),remark=optional(raw.remark(),500);if(phone==null&&source==null&&qr==null)throw invalid("电话、1688 链接、微信二维码至少填写一项");Status status=raw.status()==null?Status.ACTIVE:raw.status();if(!existing&&status==Status.DISABLED)throw invalid("新供应商不能直接停用");return new Input(name,contact,phone,source,qr,remark,status,raw.version());}
private String url(String value){String result=optional(value,500);if(result==null)return null;try{URI uri=URI.create(result);String host=uri.getHost();if(!"https".equalsIgnoreCase(uri.getScheme())||host==null||uri.getUserInfo()!=null||!(host.equalsIgnoreCase("1688.com")||host.toLowerCase(Locale.ROOT).endsWith(".1688.com")))throw invalid("采购链接必须为 1688.com 或其子域的 HTTPS 地址");return uri.toASCIIString();}catch(SupplierException e){throw e;}catch(IllegalArgumentException e){throw invalid("采购链接格式不正确");}}
private String required(String v,String label,int max){String r=optional(v,max);if(r==null)throw invalid(label+"不能为空");return r;}private String optional(String v,int max){if(v==null)return null;String r=v.trim();if(r.isEmpty())return null;if(r.length()>max||r.chars().anyMatch(c->c<32))throw invalid("字段格式或长度不正确");return r;}
private SupplierException invalid(String m){return new SupplierException(400,"SUPPLIER_FIELD_INVALID",m);}private SupplierException conflict(){return new SupplierException(409,"SUPPLIER_VERSION_CONFLICT","供应商已被其他用户更新");}private SupplierException missing(String id){return new SupplierException(404,"SUPPLIER_NOT_FOUND","供应商不存在："+id);}
private Map<String,Object> snapshot(View v){Map<String,Object> m=new LinkedHashMap<>();m.put("id",v.id());m.put("name",v.name());m.put("phone",mask(v.phone()));m.put("sourceHost",v.sourceUrl()==null?null:URI.create(v.sourceUrl()).getHost());m.put("qrImageId",v.qrImageId());m.put("status",v.status());m.put("version",v.version());return m;}
private String mask(String phone){if(phone==null)return null;if(phone.length()<=4)return "****";return phone.substring(0,2)+"****"+phone.substring(phone.length()-2);}
private void audit(AuthenticatedActor a,String action,String id,Map<String,?>before,Map<String,?>after){audit.record(new AuditTrail.BusinessOperation(a.userId(),a.loginName(),a.displayName(),action,"SUPPLIER",id,true,before,after,"供应商档案或关联变更"));}
}
